def parse_kv(s):
    if not s:
        return {}

    # Handle escaped semicolons (\;) by replacing them with a placeholder
    placeholder = "__ESCAPED_SEMICOLON__"
    # Note: In string literals, a backslash must be escaped, so r'\;' is used to match a literal '\;'
    s_processed = s.replace(r'\;', placeholder)

    # Split by unescaped semicolon and filter out empty parts
    pairs = [p.strip() for p in s_processed.split(';') if p.strip()]

    result = {}

    for pair in pairs:
        if '=' not in pair:
            continue 

        # Find the first '='
        key_end = pair.find('=')
        key = pair[:key_end].strip()
        value = pair[key_end+1:].strip()

        # Restore the literal semicolon if the placeholder was used
        value = value.replace(placeholder, r';')

        if key:
            result[key] = value

    return result

