import pytest
from parse_kv import parse_kv

def test_empty_string():
    assert parse_kv("") == {}

def test_basic_pairs():
    assert parse_kv("key1=value1; key2=value2") == {"key1": "value1", "key2": "value2"}

def test_whitespace_trimming():
    assert parse_kv("  key1 = value1 ; key2 = value2 ") == {"key1": "value1", "key2": "value2"}

def test_escaped_semicolon_in_value():
    # The input should contain '\;' to represent a literal semicolon inside the value
    assert parse_kv("key1=value_with_semi\\;colon") == {"key1": "value_with_semi;colon"}

def test_multiple_semicolons():
    assert parse_kv("a=1; b=2; c=3") == {"a": "1", "b": "2", "c": "3"}

def test_mixed_whitespace_and_empty_parts():
    # Testing robustness against extra spaces or empty segments
    assert parse_kv("a=1; ; b=2 ; ") == {"a": "1", "b": "2"}

def test_no_equals():
    # Should ignore parts without '='
    assert parse_kv("invalid_pair; key1=value1") == {"key1": "value1"}

def test_complex_case():
    # Complex scenario combining trimming, escaped semicolon, and multiple pairs
    s = "  k1 = v1; k2 = v2\\;v3 ; k3 = value_with_equal=sign"
    expected = {"k1": "v1", "k2": "v2;v3", "k3": "value_with_equal=sign"}
    assert parse_kv(s) == expected

